const Anthropic = require\('@anthropic-ai/sdk'\);
const client = new Anthropic\({ apiKey: require\('dotenv'\).config\({path:'.env.local'}\).parsed.ANTHROPIC_API_KEY }\);

const fakeScraped = {
  name: 'Test Product',
  description: 'A test product for testing',
  images: [],
  price: null,
  brandColors: { primary: '#FFD659', secondary: '#0F0F23', accent: '#FF6B6B' },
  features: ['Feature 1', 'Feature 2'],
  socialProof: { reviews: null, rating: null },
  rawText: 'Test product raw text'
};

const prompt = 'You are a senior Meta ads strategist. PRODUCT DATA: ' + JSON.stringify\(fakeScraped\) + '. Extract productName, oneLiner, problem, features array, competitiveEdge, pricePosition, trustSignals, emotionalTriggers, and trendBrief with viralHooks, visualTrends, copyFrameworks, audienceInsights, competitorMoves, seasonalAngle. Return ONLY valid JSON. No markdown.';

client.messages.create\({
  model: 'claude-sonnet-4-20250514',
  max_tokens: 4000,
  tools: [{type:'web_search_20250305', name:'web_search', max_uses:5}],
  messages: [{role:'user', content: prompt}]
}\).then\(r => {
  console.log\('Blocks:', r.content.map\(b => b.type\)\);
  const textBlocks = r.content.filter\(b => b.type === 'text'\);
  console.log\('Text blocks count:', textBlocks.length\);
  if \(textBlocks.length > 0\) {
    const last = textBlocks[textBlocks.length-1].text;
    console.log\('Last text \(first 500\):', last.slice\(0, 500\)\);
    // Try parse
    try {
      const cleaned = last.trim\(\).replace\(/^\\`\\`\\`\(?:json\)?\\s*/i,''\).replace\(/\\s*\\`\\`\\`$/,''\).trim\(\);
      JSON.parse\(cleaned\);
      console.log\('JSON PARSE: OK'\);
    } catch\(e1\) {
      const m = last.match\(/\\\\{[\\\\s\\\\S]+\\\\}/\);
      if \(m\) {
        try { JSON.parse\(m[0]\); console.log\('REGEX JSON PARSE: OK'\); } catch { console.log\('REGEX PARSE FAIL'\); }
      } else {
        console.log\('NO JSON FOUND IN RESPONSE'\);
      }
    }
  }
  console.log\('Stop reason:', r.stop_reason\);
}\).catch\(e => console.error\('ERROR:', e.status, e.message\)\);
